// UI font for the control panel: Plus Jakarta Sans (SIL Open Font License 1.1, see lib/fonts/PlusJakartaSans-OFL.txt).
// Embedded so it also works when the page is opened from disk (Chrome blocks font files over file://).
(function () {
  if (typeof FontFace === 'undefined' || !document.fonts) return;
  for (const f of [{"range":"U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD","data":""},{"range":"U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF","data":""}]) {
    const bytes = Uint8Array.from(atob(f.data), (c) => c.charCodeAt(0));
    const face = new FontFace('Plus Jakarta Sans', bytes.buffer, { weight: '200 800', style: 'normal', unicodeRange: f.range, display: 'swap' });
    document.fonts.add(face);
    face.load().catch(() => {});
  }
})();
